INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-clinical-mnt', 'Clinical Nutrition & MNT', 'Core Medical Nutrition Therapy concepts, disease diets, renal staging, and enteral/parenteral nutrition.', 'Clinical Nutrition', 'Stethoscope', '#7FA98B', '["MNT","Renal","GI","ICU","Endocrine"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-biochem-vitamins', 'Biochemistry & Vitamin Deficiencies', 'Vitamins, coenzymes, metabolic pathways, and classic deficiency syndromes.', 'Nutritional Biochemistry', 'Sparkles', '#FF9A76', '["Vitamins","Metabolism","Deficiencies"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-foodservice-formulas', 'Food Service & Dietetic Calculations', 'Formulas for IBW, food cost %, scoop conversions, inventory markup, and Atwater factors.', 'Food Service Systems', 'Calculator', '#D4A373', '["Formulas","Calculations","Management","Anthropometrics"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-foodservice-ndle2021', 'Food Service - NDLE 2021 Exam', 'Complete 200-question board exam reviewer from Quizlet covering Food Service Systems, Food Microbiology, Management, Costing, and Meal Management.', 'Food Service Systems', 'Calculator', '#D4A373', '["Food Service","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-clinical-biochem-ndle', 'Clinical Dietetics & Nutritional Biochemistry - NDLE Bank', 'Comprehensive high-yield NDLE board examination reviewer covering Medical Nutrition Therapy (MNT), Renal, Enteral/Parenteral, Diabetes, Inborn Errors, and Vitamins/Metabolism.', 'Nutritional Biochemistry', 'Stethoscope', '#059669', '["Clinical Nutrition","Nutritional Biochemistry","MNT","NDLE","NBCD"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-cphn-ndle-bank', 'Community & Public Health Nutrition - NDLE Bank', 'High-yield Philippine NDLE board exam questions covering the Philippine Plan of Action for Nutrition (PPAN), Operation Timbang Plus, RA 11148 (First 1000 Days), Food Fortification, Nutrition Assessment, and Public Health Epidemiology.', 'Public Health & Community', 'Users', '#2563eb', '["Community Nutrition","Public Health","CPHN","NDLE","PPAN","NNC"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.decks (id, title, description, category, icon, color, tags, updated_at) VALUES ('deck-cble-mock-bank', 'CBLE Mock Examination Bank', 'Supplemental simulated examination cards and case studies.', 'General Dietetics', 'GraduationCap', '#6366f1', '["CBLE","Mock Exam","NDLE"]'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, icon = EXCLUDED.icon, color = EXCLUDED.color, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-mnt-1', 'deck-clinical-mnt', 'What is the recommended protein intake for a non-dialysis Chronic Kidney Disease (CKD) patient in Stage 4 (GFR 15–29 mL/min)?', '0.6 to 0.8 g/kg body weight/day', 'For CKD Stages 3–5 (non-dialysis), protein is restricted to 0.6–0.8 g/kg/day to slow renal disease progression and decrease uremic toxin accumulation. Once on hemodialysis, protein requirement increases to 1.2–1.4 g/kg/day due to dialysate losses.', '["0.6 to 0.8 g/kg body weight/day","1.2 to 1.4 g/kg body weight/day","1.5 to 2.0 g/kg body weight/day","0.3 to 0.5 g/kg body weight/day"]'::jsonb, '["CKD","Renal","Protein"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.658Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-mnt-2', 'deck-clinical-mnt', 'What is the maximum osmolarity cutoff for Peripheral Parenteral Nutrition (PPN) infusion to avoid phlebitis?', '900 mOsm/L', 'Peripheral veins can tolerate solutions up to ~900 mOsm/L. Solutions exceeding 900 mOsm/L are hypertonic and must be infused via Central Parenteral Nutrition (CPN / TPN) through a large central vein (e.g., subclavian/jugular) where high blood flow rapidly dilutes the solution.', '["900 mOsm/L","500 mOsm/L","1500 mOsm/L","300 mOsm/L"]'::jsonb, '["Parenteral","Osmolarity","ICU"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-mnt-3', 'deck-clinical-mnt', 'What is the classic dietary fat to combined carbohydrate + protein ratio used in the Ketogenic Diet for refractory pediatric epilepsy?', '4:1 (or 3:1) ratio', 'The classic ketogenic diet uses a 4:1 ratio of fat (in grams) to combined carbohydrate and protein (in grams), providing ~90% of calories from fat to induce and sustain ketosis, providing ketone bodies (beta-hydroxybutyrate) as the primary cerebral fuel.', '["4:1 (or 3:1) ratio","1:1 ratio","2:1 ratio","5:2 ratio"]'::jsonb, '["Pediatric","Epilepsy","Ketogenic"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-mnt-4', 'deck-clinical-mnt', 'Which specific storage protein (prolamin) in wheat triggers the autoimmune enteropathy in Celiac Disease?', 'Gliadin', 'Celiac disease is triggered by the ingestion of gluten prolamins: Gliadin in wheat, Secalin in rye, and Hordein in barley. These induce immune-mediated small intestinal mucosal inflammation and villous atrophy.', '["Gliadin","Glutenin","Casein","Zein"]'::jsonb, '["GI","Celiac","Gluten"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-mnt-5', 'deck-clinical-mnt', 'What sodium limit is recommended in the strict DASH (Dietary Approaches to Stop Hypertension) diet trial?', '1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)', 'The standard DASH diet limits sodium to 2,300 mg/day, while the lower-sodium DASH plan caps sodium at 1,500 mg/day. It emphasizes potassium, calcium, magnesium, fiber, and lean proteins.', '["1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)","500 mg/day","3,500 mg/day","1,000 mg/day max"]'::jsonb, '["Cardiovascular","Hypertension","DASH"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-bio-1', 'deck-biochem-vitamins', 'Wernicke-Korsakoff syndrome and Beriberi are caused by a severe deficiency of which water-soluble vitamin?', 'Thiamine (Vitamin B1)', 'Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.', '["Thiamine (Vitamin B1)","Riboflavin (Vitamin B2)","Niacin (Vitamin B3)","Pyridoxine (Vitamin B6)"]'::jsonb, '["Vitamins","B1","Deficiency"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-bio-2', 'deck-biochem-vitamins', 'What are the classic "4 Ds" characteristic of severe Pellagra (Niacin / Vitamin B3 deficiency)?', 'Dermatitis, Diarrhea, Dementia, and Death', 'Pellagra presents with the 4 Ds: Photosensitive symmetrical Dermatitis (Casal necklace), Diarrhea, Dementia/delirium, and Death if untreated. 60 mg of dietary tryptophan can synthesize approximately 1 mg of niacin in the liver.', '["Dermatitis, Diarrhea, Dementia, and Death","Dyspnea, Dysphagia, Dysuria, and Dehydration","Dizziness, Depression, Dyspepsia, and Dermatitis","Diplopia, Dysarthria, Dysphagia, and Dysmetria"]'::jsonb, '["Niacin","B3","Pellagra"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-bio-3', 'deck-biochem-vitamins', 'Vitamin C (Ascorbic Acid) is an essential cofactor for which enzymatic reaction during collagen biosynthesis?', 'Hydroxylation of Proline and Lysine residues', 'Ascorbic acid maintains iron in its ferrous (Fe2+) state, serving as a reducing agent for prolyl hydroxylase and lysyl hydroxylase. Without it, defective triple-helix collagen fibers fail to crosslink, leading to Scurvy (fragile capillaries, bleeding gums, impaired wound healing).', '["Hydroxylation of Proline and Lysine residues","Decarboxylation of Glutamate to GABA","Methylation of Homocysteine to Methionine","Transamination of Alanine to Pyruvate"]'::jsonb, '["Vitamin C","Collagen","Enzyme"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-bio-4', 'deck-biochem-vitamins', 'Where is the Vitamin B12 (Cobalamin) – Intrinsic Factor complex primarily absorbed in the human gastrointestinal tract?', 'Terminal Ileum', 'Dietary B12 binds haptocorrin in saliva/gastric juice, is transferred to gastric parietal cell-secreted Intrinsic Factor (IF) in the duodenum, and the intact B12-IF complex is absorbed via cubam receptors in the Terminal Ileum.', '["Terminal Ileum","Duodenum","Proximal Jejunum","Ascending Colon"]'::jsonb, '["B12","GI","Absorption"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-bio-5', 'deck-biochem-vitamins', 'Which amino acid serves as the biological precursor for endogenous synthesis of Niacin (NAD/NADP)?', 'Tryptophan', 'Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).', '["Tryptophan","Tyrosine","Phenylalanine","Methionine"]'::jsonb, '["Biochemistry","AminoAcids","Niacin"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-fs-1', 'deck-foodservice-formulas', 'Using the Hamwi Formula, what is the Ideal Body Weight (IBW) for an adult female who is 5 feet 5 inches tall with a medium frame?', '125 lbs (± 10% for frame size)', 'Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).', '["125 lbs (± 10% for frame size)","135 lbs (± 10% for frame size)","115 lbs (± 10% for frame size)","120 lbs (± 10% for frame size)"]'::jsonb, '["Hamwi","IBW","Anthropometrics"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-fs-2', 'deck-foodservice-formulas', 'What is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?', '32 ÷ Scoop Number = fluid ounces', 'Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).', '["32 ÷ Scoop Number = fluid ounces","64 ÷ Scoop Number = fluid ounces","16 ÷ Scoop Number = fluid ounces","Scoop Number × 4 = fluid ounces"]'::jsonb, '["FoodService","PortionControl","Scoop"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-fs-3', 'deck-foodservice-formulas', 'If a recipe costs $1.80 per portion to produce and the target Food Cost Percentage is 30%, what is the selling price using the Factor Pricing Method?', '$6.00', 'Markup Factor = 100 ÷ Target Food Cost % = 100 ÷ 30 = 3.333. Selling Price = Raw Food Cost × Markup Factor = $1.80 × 3.333 = $6.00 (Alternatively: $1.80 ÷ 0.30 = $6.00).', '["$6.00","$5.40","$7.20","$4.50"]'::jsonb, '["Pricing","FoodCost","Management"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-fs-4', 'deck-foodservice-formulas', 'What are the physiological fuel values (Atwater General Energy Factors) for Carbohydrates, Protein, Fat, and Alcohol in kcal/gram?', 'Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g', 'Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.', '["Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g","Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 8 kcal/g | Alcohol: 5 kcal/g","Carb: 3.75 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 9 kcal/g","Carb: 5 kcal/g | Protein: 5 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g"]'::jsonb, '["Atwater","Energy","Macronutrients"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-fs-5', 'deck-foodservice-formulas', 'What is the formula for Adjusted Body Weight (ABW) commonly used for obese patients in clinical nutrition calculations?', 'ABW = IBW + 0.25 × (Actual Weight – IBW)', 'In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.', '["ABW = IBW + 0.25 × (Actual Weight – IBW)","ABW = Actual Weight – 0.50 × IBW","ABW = (Actual Weight + IBW) ÷ 2","ABW = IBW + 0.50 × (Actual Weight – IBW)"]'::jsonb, '["ABW","Clinical","Formulas"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-10-31T09:39:23.659Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-1', 'deck-foodservice-ndle2021', 'Garlic, onions, and shallots are example of:', 'Bulbs', 'Garlic, onions, and shallots are bulbs.', '["Roots and Tubers","Shoots","Seeds","Bulbs"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-2', 'deck-foodservice-ndle2021', 'Overboiling of eggs will result to:', 'Coagulation', 'Proteins thicken when heated in a process known as coagulation.', '["Formation of acrolein","Coagulation","Gelatinization","Rancidity"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-3', 'deck-foodservice-ndle2021', 'What condition favors the growth of Clostridium Botulinum?', 'Absence of air and low acidic environment', 'Clostridium botulinum thrives in anaerobic (air-tight) and low-acid (pH > 4.6) environments.', '["At very high temperature","Absence of air and low acidic environment","At freezing temperatures","Presence of air and high acidic environment"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-4', 'deck-foodservice-ndle2021', 'Which of the ff milk products has the longest shelf life?', 'Ultra High Temp. (UHT) Milk', 'UHT milk is heated to high sterilization temperatures and packed in aseptic packaging, giving it up to 3 months shelf life.', '["Fresh Milk","Evaporated Milk","Ultra High Temp. (UHT) Milk","Condensed Milk"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-5', 'deck-foodservice-ndle2021', 'This food additive is added in salad dressings to allow smooth mixture of ingredients without separation. Examples of this additive are soy, lecithin, and egg yolks.', 'Emulsifiers', 'Emulsifiers have hydrophilic and hydrophobic ends that keep oil and water mixed.', '["Humectants","Emulsifiers","Leavening Agents","pH Control Agents"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-6', 'deck-foodservice-ndle2021', 'How do you ensure tenderness of a thick crust pizza?', 'Lower the temperature and slow cook.', 'Lowering the temperature and slow cooking allows thick crust dough to cook through without toughening.', '["Lower the temperature and slow cook.","Apply oil or soft. fats on the crust before cooking.","Add more vegetables as toppings after cooking.","Add more pineapple as toppings during cooking"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
