INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-26', 'deck-foodservice-ndle2021', 'The ''A'' in FATTOM, an acronym used to describe the conditions in microbial growth, means:', 'Acidity', 'FATTOM: Food, Acidity, Time, Temperature, Oxygen, Moisture.', '["Alkalinity","Agent","Acidity","Anti-bacterial"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-27', 'deck-foodservice-ndle2021', 'These are non-digestible food substances that stimulate the growth of good bacteria in the gut.', 'Prebiotics', 'Prebiotics are non-digestible fiber compounds that feed gut probiotics.', '["Probiotics","Functional food","Phytochemicals","Prebiotics"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-28', 'deck-foodservice-ndle2021', 'It is an organism able to grow at high temperature.', 'Thermophiles', 'Thermophiles are heat-loving microorganisms (50-80°C).', '["virus","Thermophiles","Psychotrophs","Bacteria"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-29', 'deck-foodservice-ndle2021', 'It is an organism able to grow in cold temperature.', 'Psychotrophs', 'Psychrotrophs grow in cold temperatures (0-5°C).', '["virus","Thermophiles","Psychotrophs","Bacteria"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-30', 'deck-foodservice-ndle2021', 'This occurs during the first five minutes of baking due to the acceleration of fermentation due to the heat, causing the rise of the dough.', 'Oven spring', 'Oven spring is the rapid expansion of dough during the initial minutes of baking.', '["Gelatinization","Proofing","Punching","Oven spring"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-31', 'deck-foodservice-ndle2021', 'This occurs during the final rise of the dough before baking.', 'Proofing', 'Proofing is the final rising phase of shaped dough before baking.', '["Gelatinization","Proofing","Punching","Oven spring"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-32', 'deck-foodservice-ndle2021', 'Identify the dishes which are popular in the Visayas and Mindanao Region.', 'Bas-uy, Linat-an and Paklay', 'Bas-uy, Linat-an, and Paklay are popular in Visayas/Mindanao.', '["Sinigang na Kanduli, sisig and Bringhe","Laing, Tinuktok and Sinanglay","Apan-apan, Chicken Binakol, and Utan","Bas-uy, Linat-an and Paklay"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-33', 'deck-foodservice-ndle2021', 'Identify the dishes which are popular in different regions (Central Luzon):', 'Sinigang na Kanduli, sisig and Bringhe', 'Sinigang na Kanduli, Sisig, and Bringhe are Central Luzon specialties.', '["Sinigang na Kanduli, sisig and Bringhe","Laing, Tinuktok and Sinanglay","Apan-apan, Chicken Binakol, and Utan","Bas-uy, Linat-an and Paklay"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-34', 'deck-foodservice-ndle2021', 'Identify the dishes which are popular in Western Visayas region?', 'Apan-apan, Chicken Binakol, and Utan', 'Apan-apan and Chicken Binakol are Western Visayas specialties.', '["Sinigang na Kanduli, sisig and Bringhe","Laing, Tinuktok and Sinanglay","Apan-apan, Chicken Binakol, and Utan","Bas-uy, Linat-an and Paklay"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-35', 'deck-foodservice-ndle2021', 'Identify the dishes which are popular in Bicol region, Southern Luzon?', 'Laing, Tinuktok and Sinanglay', 'Laing, Tinuktok, and Sinanglay originate from Bicol.', '["Sinigang na Kanduli, sisig and Bringhe","Laing, Tinuktok and Sinanglay","Apan-apan, Chicken Binakol, and Utan","Bas-uy, Linat-an and Paklay"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-36', 'deck-foodservice-ndle2021', 'Food is hot filled into the container then sealed under aseptic conditions and processed immediately is called?', 'Hot pack method', 'Hot pack method involves heating food to >85°C and sealing in sterile containers.', '["Open kettle","Hot pack method","Cold pack method","Pasteurization"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-37', 'deck-foodservice-ndle2021', 'The browning of baked products is due to?', 'Maillard Reaction', 'Maillard reaction occurs between amino acids and reducing sugars under heat.', '["Chymosin","Enzymatic browning","Buffering","Maillard Reaction"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-38', 'deck-foodservice-ndle2021', 'What is a right of employees concerning vacation leaves, working hours and holidays?', 'Right to be paid accordingly', 'Employees have the statutory right to be compensated accordingly under the Labor Code.', '["Right to be paid accordingly","Right to a meal allowance","Right for emergency allowance","Minimun wage"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-39', 'deck-foodservice-ndle2021', 'Which government agency is responsible in licensing, monitoring, and regulating the food products being sold in the market?', 'Food and Drug Administration', 'The FDA regulates and licenses food and drug safety.', '["Food and Nutrition Research Institute","Bureau of Food and Fisheries","Bureau of Food and drugs","Food and Drug Administration"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-40', 'deck-foodservice-ndle2021', 'Which is a type of food spoilage that includes enzymatic reactions in living things as influenced by temperature, moisture, pH and the nutrients present?', 'Biochemical spoilage', 'Biochemical spoilage involves natural internal enzyme reactions.', '["Spoilage by microorganisms","Biochemical spoilage","Chemical deterioration","Physical deterioration"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-41', 'deck-foodservice-ndle2021', 'The labor cost for a certain dish is Php20 per hour. If it takes 45 minutes to make the dish, what is the labor cost for this particular dish?', 'Php 15', '45/60 hr = 0.75 hr x P20 = P15.', '["Php 10","Php 15","Php 28","Php 20"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-42', 'deck-foodservice-ndle2021', 'The enzyme which is important for cheese production is?', 'renin', 'Renin / chymosin curdles milk protein in cheese making.', '["papain","bromelain","renin","polyphenol oxidase"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-43', 'deck-foodservice-ndle2021', 'The softest cheese among the following is:', 'Brie', 'Brie is a soft-ripened cheese with the highest moisture content.', '["Gouda","Brie","Edam","Cheddar"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-44', 'deck-foodservice-ndle2021', 'Choose a form of disaccharide usually used in the production of beer.', 'Maltose', 'Maltose is the primary malt sugar fermented in beer production.', '["Maltose","Sucrose","Lactose","Glucose"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-45', 'deck-foodservice-ndle2021', 'ESSENTIAL amino acids are:', 'histidine, isoleucine, leucine', 'Histidine, isoleucine, and leucine are essential amino acids.', '["Aspartic acid, cysteine, glutamic acid","alanine, arginine, asparagine","histidine, isoleucine, leucine","proline, serine, tyrosine"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-46', 'deck-foodservice-ndle2021', 'Which is NOT true about Churros?', 'It is a baked pastry.', 'Churros are fried, not baked.', '["It is like fried donut.","Spanish cuisine","It is a baked pastry.","It is served with chocolate."]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-47', 'deck-foodservice-ndle2021', 'During a review of customer feedback survey, Michelle, RND, noted pattern of dissatisfaction with the consistency of the quality of the beef caldereta. The most likely cause for the problem would be:', 'the cooks are not using the standardized recipe.', 'Consistency depends on strict adherence to standardized recipes.', '["diners are unaware of the true taste of beef caldereta.","the quality of the beef used not consistent with the specifications.","the waiters are not using the appropriate size dishes when plating the dish","the cooks are not using the standardized recipe."]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-48', 'deck-foodservice-ndle2021', 'What dish can be made to utilize left over steamed kangkong from the last family dinner?', 'Utan', 'Utan is a vegetable stew ideal for utilizing leafy greens like kangkong.', '["Utan","Baye bave","Dinakdakan","Sisig"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-49', 'deck-foodservice-ndle2021', 'The ''F'' in FATTOM, an acronym used to describe the conditions in microbial growth, means', 'Food', 'F stands for Food in FATTOM.', '["Fasting","Food","Fahrenheit","Fat"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-50', 'deck-foodservice-ndle2021', 'Which kind of damage results from dehydration of a frozen breaded chicken patty due to extreme cold?', 'Freezer burn', 'Freezer burn is moisture sublimation from frozen foods.', '["Crystallization","Freezer burn","Caking","Contamination due to excessive additives"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-51', 'deck-foodservice-ndle2021', 'How do you call the bacteria which can be found in powdered infant formula which can cause meningitis?', 'Enterobacter sakazaki', 'Enterobacter sakazakii (Cronobacter sakazakii) can survive in powdered infant formula and cause neonatal meningitis.', '["Staphylococcus aureus","Bacillus cereus","Clostridium botulinum","Enterobacter sakazaki"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-52', 'deck-foodservice-ndle2021', 'What will happen to sugar if it is heated above, 160 degrees C?', 'Caramelization', 'Caramelization occurs at 160-170°C where sucrose decomposes into aromatic caramel compounds.', '["Burnt fat","Denaturation","Caramelization","Crystallization"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-53', 'deck-foodservice-ndle2021', 'Which department is NOT involved in the receiving process in hospital''s foodservice?', 'HR', 'Human Resources does not participate in the daily food receiving dock operations.', '["Dietary","Accounting","Purchasing","HR"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-54', 'deck-foodservice-ndle2021', 'The muscle pigment is called', 'Myoglobin', 'Myoglobin is the primary heme iron protein pigment in muscle tissue.', '["Hemoglobin","Nitroso myoglobin","Myoglobin","Nitrosohemochrome"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-55', 'deck-foodservice-ndle2021', 'select the BEST way to manage leftovers from the morning buffet at the hotel', 'Sell leftovers at the employees cafeteria at low cost', 'Selling leftovers at employee cafeteria minimizes waste and recovers cost safely.', '["Serve the same food to the diners for lunch and dinner","Sell leftovers at the employees cafeteria at low cost","Freeze the leftover and serve the following day","Let the employees take out all the leftovers everyday"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-56', 'deck-foodservice-ndle2021', 'Which is true about passing the licensure examination for ND based on the ND law in 2016?', 'Must have a general average of 75% with no rating below 70% in any subjects', 'RA 10862 requires a 75% general average with no grade below 70%.', '["Must have a general average of 70% with no rating below 70%, in any subjects","Must have a general average of 75% with no rating below 70% in any subjects","Must obtain at least 80% general average in all of the subjects","Must have a general average of 75% with no rating below 50% in any subjects"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-57', 'deck-foodservice-ndle2021', 'Identify the thread-like noodles which made from cassava and wheatflour?', 'Miswa', 'Miswa are thread-like wheat and cassava salted noodles.', '["Instant noodles","Miswa","Sotanghon","Soba"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-58', 'deck-foodservice-ndle2021', 'Identify the noodles also known as cellophane or glass noodles made from potato, mung bean, sweet potato, or tapioca starch and water?', 'Sotanghon', 'Sotanghon (glass noodles) are made from mung bean or starch.', '["Instant noodles","Miswa","Sotanghon","Soba"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-59', 'deck-foodservice-ndle2021', 'Lutong Bahay canteen is operating in Makati. All the food preparation is done in the area. It also accommodates short orders like pancit and tapsilog. This foodservice system is:', 'conventional', 'Conventional systems prepare and cook all food on-site for immediate service.', '["ready-prepared","commissary","conventional","assembly serve"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-60', 'deck-foodservice-ndle2021', 'is a system where food is prepared and cooked off-site, and then transported to the foodservice establishment to be re-heated and served.', 'ready-prepared', 'Ready-prepared / cook-chill prepares foods in advance for reheating.', '["ready-prepared","commissary","conventional","assembly serve"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-61', 'deck-foodservice-ndle2021', 'is a system where food is prepared and cooked in a central kitchen, and then distributed to multiple foodservice establishments.', 'commissary', 'Commissary systems utilize a central production kitchen distributing to satellite units.', '["ready-prepared","commissary","conventional","assembly serve"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-62', 'deck-foodservice-ndle2021', 'is a system where food is prepared in advance, and then assembled at the area and served to customers.', 'assembly serve', 'Assembly-serve (kitchenless kitchen) uses pre-portioned prepared foods requiring only heating and assembly.', '["ready-prepared","commissary","conventional","assembly serve"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-63', 'deck-foodservice-ndle2021', 'Which of the following foods are responsible for most allergic reactions?', 'Egg, milk, peanuts', 'Egg, milk, and peanuts account for the vast majority of pediatric and adult food allergies.', '["Eggplant, tofu, soybeans","Chicken, beans, eggplant","Garlic, onion, pork","Egg, milk, peanuts"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-64', 'deck-foodservice-ndle2021', 'What is the most cost-efficient way of scouting for an applicant for a mid-level to high-level position?', 'via Linkedin', 'LinkedIn provides targeted professional networking and recruitment.', '["via Linkedin","Publishing a position in newspaper","via Twitter","Conducting a job fair"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-65', 'deck-foodservice-ndle2021', 'Laing and Binangol are both dishes made from gabi leaves and coconut milk. Laing is a dish from Bicol while Binangol is from:', 'Eastern Visayas', 'Binagol is a famous taro dessert from Leyte (Eastern Visayas).', '["Batanes","Southern Tagalog","Ilocos","Eastern Visayas"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-66', 'deck-foodservice-ndle2021', 'Which is NOT a characteristic of a fresh egg?', 'Unporous shell', 'Eggshells are naturally porous to allow gas exchange.', '["well concentrated egg yolk","Firm albumen","No germ spot","Unporous shell"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-67', 'deck-foodservice-ndle2021', 'How many pints are there in 1 quart?', '2 pints', '1 quart = 2 pints = 4 cups = 32 fluid ounces.', '["4 pints","6 pints","2 pints","8 pints"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-68', 'deck-foodservice-ndle2021', 'The three categories of food contaminants are best described as:', 'Chemical, Biological, and Physical Hazards', 'The three classic food safety hazard categories are Biological, Chemical, and Physical.', '["Chemical, Customer, and Staff Hazards","External, Internal, and Customer Hazards","Chemical, Biological, and Physical Hazards","Human, Microbial, and Viral Hazards"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-69', 'deck-foodservice-ndle2021', 'Substances in plant-based foods with physiologically active compounds that have functional benefits are called:', 'Phytochemicals', 'Phytochemicals (phytonutrients) are plant bioactive compounds conferring health benefits.', '["Probiotics","Functional food","Phytochemicals","Prebiotics"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-70', 'deck-foodservice-ndle2021', 'The mother sauce of all white sauces is called:', 'Bechamel', 'Bechamel (white roux + milk) is the classic white mother sauce.', '["Roux","Espagnole","Consomme","Bechamel"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-71', 'deck-foodservice-ndle2021', 'This is a paste that is used to make hummus.', 'Tahini', 'Tahini is ground toasted sesame seed paste used in hummus.', '["Yogurt.","Bean curd","Tahini","Baba. Ghanoush"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-72', 'deck-foodservice-ndle2021', 'Oxidative rancidity happens in foods that have:', 'High in unsaturated fat', 'Unsaturated fats contain double bonds that are highly susceptible to free radical oxidation.', '["High in saturated fat","High in moisture content","High in protein content","High in unsaturated fat"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-73', 'deck-foodservice-ndle2021', 'When one person or department purchases for every department, it is called:', 'Centralized', 'Centralized purchasing consolidates buying power and standardizes specifications.', '["Open market","Centralized","E-commerce","Bidding"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-74', 'deck-foodservice-ndle2021', 'This method is often used for products that are not purchased frequently, or for products that are difficult to standardize.', 'Open market', 'Open market / informal purchasing is used for small, urgent, or perishable goods.', '["Open market","Centralized","E-commerce","Bidding"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-75', 'deck-foodservice-ndle2021', 'It is a competitive process, wherein two or more entities try to outbid each other by raising the amount they''re willing to pay in order to win the asset.', 'Bidding', 'Bidding is a competitive pricing and contract award process.', '["Open market","Centralized","E-commerce","Bidding"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-76', 'deck-foodservice-ndle2021', 'If you open sealed bids and place the order with the lowest bid, you are using which buying method?', 'Competitive bid', 'Competitive formal bidding awards the lowest responsible conforming bidder.', '["Open market","Informal bid","Competitive bid","E-commerce"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-77', 'deck-foodservice-ndle2021', 'Which of the following factors would be most important to determine the food cost per serving for fruits and vegetables?', 'Edible portion', 'Edible portion (EP) yield determines the actual usable food cost per serving.', '["Maturity and availability","Edible portion","Budget allocation","Size and shape"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-78', 'deck-foodservice-ndle2021', 'Rigor mortis is an example of what spoilage?', 'Biochemical', 'Rigor mortis is post-mortem biochemical muscle contraction and ATP depletion.', '["Physical","Biochemical","Chemical","Microorganism-caused"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-79', 'deck-foodservice-ndle2021', 'A cold soup in Spanish cuisine which contains cucumber, peppers, tomatoes, oils, vinegar, and bread.', 'Gazpacho', 'Gazpacho is an Andalusian cold raw vegetable soup.', '["Cold Sopas","Gazpacho","Paella","Vichyssoise"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-80', 'deck-foodservice-ndle2021', 'a Filipino macaroni soup made with elbow macaroni, various vegetables, and meat (usually chicken), in a creamy broth with evaporated milk.', 'Sopas', 'Sopas is creamy Filipino chicken macaroni soup.', '["Sopas","Gazpacho","Paella","Vichyssoise"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-81', 'deck-foodservice-ndle2021', 'a classic Spanish rice dish made with rice, saffron, vegetables, chicken, and seafood cooked and served in one pan.', 'Paella', 'Paella is a traditional Valencian saffron rice dish.', '["Sopas","Gazpacho","Paella","Vichyssoise"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-82', 'deck-foodservice-ndle2021', 'a soup made with potatoes, leeks, and cream and typically served chilled.', 'Vichyssoise', 'Vichyssoise is a French chilled potato and leek soup.', '["Sopas","Gazpacho","Paella","Vichyssoise"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
