INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-87', 'deck-foodservice-ndle2021', 'A substance that causes dough to expand by releasing gas once mixed with liquid, acid, or heat.', 'Leavening agent', 'Leavening agents produce CO2 or steam to expand baked products.', '["Leavening agent","Nutrients","Humectant","Flavor enhancer"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-88', 'deck-foodservice-ndle2021', 'These substances give baked goods optimal volume, texture and crumb and can include baking soda or baking powder, whipped egg whites or cream, active or instant dry yeast, and even steam.', 'Leavening agent', 'Chemical, biological, and physical leavening agents provide volume and structure.', '["Leavening agent","Nutrients","Humectant","Flavor enhancer"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-89', 'deck-foodservice-ndle2021', 'which of the following is NOT a beef?', 'Game', 'Game refers to wild hunted animals; cow, heifer, and stag are bovines/cattle.', '["Cow","Game","Heifer","Stag"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-90', 'deck-foodservice-ndle2021', 'Which is the second step in undertaking a research study in Foodservice?', 'State goals and objectives', 'After identifying the topic (step 1), the next step is stating objectives (step 2).', '["Determine a research topic","Prepare a conceptual framework","State goals and objectives","Define scope and limitations"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-91', 'deck-foodservice-ndle2021', 'Foods that are decomposed or produced in unsanitary conditions are considered:', 'Potentially Hazardous Foods', 'Foods held or prepared in unsanitary conditions are potentially hazardous or adulterated.', '["Potable","Adulterated Foods","Gourmet","Potentially Hazardous Foods"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-92', 'deck-foodservice-ndle2021', 'A bacon spread has a serving size of 30g. What is the equivalent household measurement?', '2 tablespoons', '1 tablespoon is ~15g, so 30g equals 2 tablespoons.', '["1 tablespoon","1 teaspoon","2 teaspoons","2 tablespoons"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-93', 'deck-foodservice-ndle2021', 'If the original yield of a macaroni salad recipe is 2.5 kg you need only 1.5kg to serve your guests, what will be the conversion factor of each ingredient to be used in the recipe?', '0.6', 'Conversion factor = Desired / Original = 1.5 / 2.5 = 0.6.', '["0.6","0.75","0.375","2"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-94', 'deck-foodservice-ndle2021', 'This is NOT a sandwich.', 'Creole', 'Creole refers to a style of cooking / cuisine, not a sandwich.', '["Canape","Clubhouse","Bahn mi","Creole"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-95', 'deck-foodservice-ndle2021', 'Samyupsal in Korea basically refers to:', 'Grilled pork belly', 'Samgyeopsal means three-layered pork belly in Korean.', '["Kimchi","Shabu shabu","Grilled pork belly","Spicy appetizer made of cabbage"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-96', 'deck-foodservice-ndle2021', 'The cause of an outbreak of a food-borne illness was traced to unpasteurized milk; symptoms included fever, nausea, headache. The Likely source is:', 'Listeria monocytogenes', 'Listeria is a psychrotolerant pathogen commonly linked to raw milk and unpasteurized soft cheeses.', '["Clostridium botulinum","Bacillus aureus","Vibrio vulnificus","Listeria monocytogenes"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-97', 'deck-foodservice-ndle2021', 'Which statement is TRUE about incomplete protein?', 'Incomplete protein will support maintenance but not growth', 'Incomplete proteins lack one or more essential amino acids and cannot independently support optimal body tissue growth.', '["Both animal meat and plants contain incomplete protein","Incomplete protein will support both maintenance and growth","Incomplete protein will support maintenance but not growth","Animal meat is a source of incomplete protein"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-98', 'deck-foodservice-ndle2021', 'Canape is a small open-faced sandwich on toast originated from where?', 'France', 'Canape is French in origin (meaning sofa/couch for toppings).', '["Puerto Rico","France","Dominican Republic","Spain"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-99', 'deck-foodservice-ndle2021', 'Which is the PRIMARY cause of food borne illness?', 'Bacteria', 'Bacteria are responsible for the vast majority of foodborne infections and intoxications.', '["Viruses","Parasites","Bacteria","Protozoa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-100', 'deck-foodservice-ndle2021', 'Acidic food: Non-acidic food:', 'Pickles; Buko water', 'Pickles are acidified (low pH), whereas coconut (buko) water is neutral/non-acidic.', '["Orange; mushroom","Pickles; Buko water","Apple; Egg white","Buko water; mushroom"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-101', 'deck-foodservice-ndle2021', 'In food preservation, the main goal is to lengthen generation time of microorganisms and as much as possible to lengthen lag phase and phase of positive acceleration. Choose one of the ways this can be done.', 'Damaging the microorganisms through heating', 'Heat processing injures or kills vegetative cells, extending lag phase and preservation.', '["Preserving the microorganisms for fermentation","Preserving the microorganisms to lengthen expiry date","Damaging the microorganisms through cooling","Damaging the microorganisms through heating"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-102', 'deck-foodservice-ndle2021', 'Identify the bacteria which can be found in rice and other starchy foods', 'Bacillus cereus', 'Bacillus cereus spores survive boiling and produce emetic toxins in fried/cooked rice left at room temperature.', '["Clostridium perfringens","Salmonella sp","Campylobacter botulinum","Bacillus cereus"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-103', 'deck-foodservice-ndle2021', 'Which is the appropriate description of a functional food?', 'It provides health benefits beyond basic nutrition', 'Functional foods provide physiological benefits or disease reduction beyond basic macro/micronutrients.', '["It stimulates growth of good bacteria in the gut.","It should be taken when a patient is under medication.","It is packed with vitamins and minerals.","It provides health benefits beyond basic nutrition"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-104', 'deck-foodservice-ndle2021', 'What is the effect of adding alcohol in cheese while cooking?', 'It prevents overheating.', 'Alcohol lowers the boiling point of fondue/sauce and prevents cheese proteins from curding/stringiness.', '["It will create Edam cheese.","It prevents overheating.","It will increase fat content.","Cheese will ferment right away."]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-105', 'deck-foodservice-ndle2021', 'What is the smoke point temperature for fats?', 'Above 350 degrees F', 'Most culinary cooking oils and fats have smoke points above 350°F (177°C).', '["Above 350 degrees F","Above 442 degrees F","Above 525 degrees F","Above 500 degrees F"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-106', 'deck-foodservice-ndle2021', 'Which is the most flavorful part of pork due to the layers of fats in between muscles?', 'Belly fat', 'Pork belly (liempo) contains intermuscular fat layers that yield superior tenderness and flavor.', '["Shouldner","Belly fat","Ribs","Kasim"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-107', 'deck-foodservice-ndle2021', 'Which is NOT a required benefit of an employee?', 'Midyear bonus', '13th month, SSS, PhilHealth, Pag-IBIG, and service incentive leaves are mandatory; midyear bonus is discretionary.', '["Vacation leave","Midyear bonus","13th month pay","SSS, Phil health, Pag Ibig"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-108', 'deck-foodservice-ndle2021', 'How do you call the poisonous toxins which can be found in peanut, tree nuts, corn and copra?', 'Aflatoxins', 'Aflatoxins are carcinogenic mycotoxins produced by Aspergillus flavus on nuts and grains.', '["Tetrodotoxin","Histamine","Aflatoxins","Plant toxins"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-109', 'deck-foodservice-ndle2021', 'Most commonly found in marine animals. It is famous for causing perioral numbness in consumers of pufferfish. Because the toxin is heat-stable, cooking does not destroy it.', 'Tetrodotoxin', 'Tetrodotoxin is a potent neurotoxin found in pufferfish (fugu) gonads/liver.', '["Tetrodotoxin","Histamine","Aflatoxins","Plant toxins"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-110', 'deck-foodservice-ndle2021', 'is a signaling chemical your immune system releases to send messages between different cells.', 'Histamine', 'Histamine mediates inflammatory and allergic responses (and scombroid poisoning).', '["Tetrodotoxin","Histamine","Aflatoxins","Plant toxins"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-111', 'deck-foodservice-ndle2021', 'Which is the commission that formulates internationally accepted food safety standards to protect the public and ensure fair trade practices?', 'Codex Alimentarius', 'Codex Alimentarius (FAO/WHO) establishes international food standards.', '["Department of Health","US FDA","Codex Alimentarius","Commission on Population"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-112', 'deck-foodservice-ndle2021', 'If a broiler is 7-12-week-old chicken, fryers are:', '14-20 weeks', 'Fryers are 14 to 20 weeks old, weighing ~0.9 to 1.5 kg more than young broilers.', '["3-5 months","10 months","14-20 weeks","11 months"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-113', 'deck-foodservice-ndle2021', 'Which additive would add sweetness, act as a stabilizer and thickener, and retain moistness in a muffin?', 'Sorbitol', 'Sorbitol is a polyol humectant and sweetener that retains moisture.', '["Sodium acetate","Sorbitol","Sodium bicarbonate","Saccharin"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-114', 'deck-foodservice-ndle2021', 'Being non-flammable, asbestos is good for:', 'Roofing material', 'Asbestos was historically used for fireproof roofing and insulation.', '["Kitchen tabletops","Cleaning agent for kitchen","Office chair","Roofing material"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-115', 'deck-foodservice-ndle2021', 'which country is known for pastries?', 'Scandinavian', 'Scandinavian countries (Denmark, Sweden, Norway) are world renowned for Danish pastries.', '["Scandinavian","India","South Africa","Mediterranean"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-116', 'deck-foodservice-ndle2021', 'Which costs will most likely be evaluated first after a budget reduction announcement?', 'Labor', 'Labor represents the largest and most flexible controllable operating expense.', '["General nonfood supplies","Equipment and maintenance","Labor","Food"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-117', 'deck-foodservice-ndle2021', 'Which of the following are conjugated proteins?', 'Nucleoprotein, mucoprotein and lipoprotein', 'Conjugated proteins contain a non-protein prosthetic group (e.g. lipid, carbohydrate, nucleic acid).', '["Albumin, nucleoproteins and peptones","Albumin, globulin and glutelin","Nucleoprotein, mucoprotein and lipoprotein","Proteans, metaproteins and peptides"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-118', 'deck-foodservice-ndle2021', 'Which milk has almost all of its fat removed?', 'Skim', 'Skim milk contains less than 0.5% milkfat.', '["25% less fat milk","Skim","Evaporated","Whole"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-119', 'deck-foodservice-ndle2021', 'What organisms can cause spoilage to food inside the refrigerator?', 'Psychotrophs', 'Psychrotrophs multiply at refrigerator temperatures (0-5°C).', '["Acidophiles","Psychotrophs","Thermophiles","Protozoa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-120', 'deck-foodservice-ndle2021', 'are microorganisms that thrive under acidic conditions, usually at very low pH (<3)', 'Acidophiles', 'Acidophiles thrive in highly acidic environments (pH < 3).', '["Acidophiles","Psychotrophs","Thermophiles","Protozoa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-121', 'deck-foodservice-ndle2021', 'They live in a wide variety of moist habitats including fresh water, marine environments and the soil. Some are parasitic, which means they live in other plants and animals including humans, where they cause disease.', 'Protozoa', 'Protozoa are single-celled eukaryotic organisms found in water/soil and include parasites.', '["Acidophiles","Psychotrophs","Thermophiles","Protozoa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-122', 'deck-foodservice-ndle2021', 'is an organism that is adapted to live at relatively high temperatures, about 60 to 140 °C (113 to 252 °F).', 'Thermophiles', 'Thermophiles are adapted to high temperatures.', '["Acidophiles","Psychotrophs","Thermophiles","Protozoa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-123', 'deck-foodservice-ndle2021', 'Chicken curry is not a popular dish in:', 'Germany', 'Curry is a staple in Southeast and South Asia, not traditional German cuisine.', '["Indonesia","India","Germany","Thailand"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-124', 'deck-foodservice-ndle2021', 'Why are molds not the common microorganisms in heated canned products?', 'Easily destroyed by heat', 'Molds and vegetative cells are destroyed at commercial canning heat (>115°C).', '["Facultative","Easily destroyed by heat","Resistant to cans","Endospores"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-125', 'deck-foodservice-ndle2021', 'Lycopene: Carotene:', 'Tomatoes, carrots', 'Tomatoes provide red lycopene; carrots provide orange carotene.', '["Tomatoes, peppers","Corn, peppers","Pineapple, carrots","Tomatoes, carrots"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-126', 'deck-foodservice-ndle2021', 'All the items below are suitable for freezing EXCEPT:', 'Mayonnaise', 'Freezing emulsion sauces like mayonnaise breaks the emulsion upon thawing.', '["Fruit Puree","Mayonnaise","Fish","Meat"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-127', 'deck-foodservice-ndle2021', 'Large group of people experience acute gastroenteritis 4 to 6 hours after eating custard pie. Which bacteria are Most likely the culprit?', 'Staphylococcus aureus', 'S. aureus produces heat-stable enterotoxins in dairy/custard pastries with 1-6 hour rapid onset.', '["Vibrio parahaemolyticus","Campylobacter jejuni","Listeria monocytogenes","Staphylococcus aureus"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-128', 'deck-foodservice-ndle2021', 'Identify the people/populations that experience the most serious consequences of foodborne illnesses.', 'Immunocompromised individuals', 'Immunocompromised individuals have the highest morbidity and mortality from foodborne infections.', '["Women of childbearing age","Teenagers","Immunocompromised individuals","Infant and young children"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-129', 'deck-foodservice-ndle2021', 'what do you call the noodles in Thailand?', 'Pad Thai', 'Pad Thai is the national stir-fried rice noodle dish of Thailand.', '["Pad Thai","Bulgogi","Bibimbap","Japchae"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-130', 'deck-foodservice-ndle2021', 'A management function that involves developing mission statements, setting goals and outlining steps needed to meet those goals.', 'Planning', 'Planning defines organizational goals and maps action pathways.', '["Controlling","Entrepreneurship","Planning","Organizing"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-131', 'deck-foodservice-ndle2021', 'Identify a wild berry which can be found in the Philippines.', 'Mulberry', 'Mulberry (Moras) is cultivated and found wild in the Philippines.', '["Atis","Mulberry","Acai","Maqui"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-132', 'deck-foodservice-ndle2021', 'The desirable pink color in cured meat is due to:', 'Nitroso myoglobin', 'Nitrite curing forms nitrosomyoglobin, which converts to stable nitrosohemochrome when cooked.', '["Metmyoglobin","Hemoglobin","Oxymyoglobin","Nitroso myoglobin"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-133', 'deck-foodservice-ndle2021', 'Difference between the cost and the selling price:', 'Markup', 'Markup is the amount added to cost price to establish selling price.', '["Variable cost","Markup","Food cost","Profit"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-134', 'deck-foodservice-ndle2021', 'Philippines: rice; Saudi Arabia:', 'Pilaf', 'Pilaf (Kabsa/rice dish) is the staple preparation in Saudi Arabia.', '["Adlai","Chia seeds","Falafel","Pilaf"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-135', 'deck-foodservice-ndle2021', 'Overcooking or overheating of oil can cause:', 'Formation of acrolein', 'Heating fats past their smoke point hydrolyzes glycerol into acrolein.', '["Coagulation","Denaturation","Gelatinization","Formation of acrolein"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-136', 'deck-foodservice-ndle2021', 'To avoid foods spoiling in the refrigerator or freezer, which of the following actions is always recommended?', 'Placing the oldest product on top of newer product', 'First-In, First-Out (FIFO) ensures older stock is rotated to the front.', '["Smelling the food to make sure it is fresh","Placing a date of arrival on all foods","Ordering foods for a few days at a time only","Placing the oldest product on top of newer product"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-137', 'deck-foodservice-ndle2021', '1 cup fresh milk: 1 cup of low fat milk:', '170kcal; 125 kcal', 'According to FEL 4th ed: 1 cup whole milk = 170 kcal, 1 cup low fat = 125 kcal.', '["100 kcal; 80 kcal","125 kcal; 80 kcal","100 kcal; 40 kcal","170kcal; 125 kcal"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-138', 'deck-foodservice-ndle2021', 'Identify the ESSENTIAL amino acids.', 'Threonin, tryptophan, valine', 'Threonine, tryptophan, and valine are essential amino acids.', '["Proline, serine, tyrosine","Threonin, tryptophan, valine","Alanine, arginine, asparagine","Aspartic acid, cysteine, glutamic acid"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-139', 'deck-foodservice-ndle2021', 'Broken mayonnaise is due to:', 'Too rapid addition of oil', 'Adding oil too quickly prevents emulsifier dispersion, breaking the emulsion.', '["Too much baking soda","Too rapid addition of oil","Too much addition of sugar","Too much addition of egg"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-140', 'deck-foodservice-ndle2021', 'Beth is a graduate of BS Nursing in one province in the Philippines. She appointed by the City Mayor to occupy the position of Nutritionist-Dietitian in an LGU. As there is an ND Law, what should the mayor do?', 'Comply with the law and replace Beth''s position with an RND', 'RA 10862 mandates that only Registered Nutritionist-Dietitians can hold ND LGU posts.', '["Give a copy of the ND law to Beth and let her decide","Wait until Beth resigns or retires and get an RND","Ask the HR in the city health office to explain the law toBeth","Comply with the law and replace Beth''s position with an RND"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-141', 'deck-foodservice-ndle2021', 'Eggs can be stored at room temperature up to:', '2 hours', 'Eggs left at room temperature should be used or refrigerated within 2 hours.', '["2 hours","7 days","14 days","1 month"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
