INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-165', 'deck-foodservice-ndle2021', 'In order to make a perfect jelly, there should be a right combination of:', 'sugar, acid and pectin', 'Jelly requires proper equilibrium of sugar (60-65%), acid (pH ~3.2), and pectin.', '["sugar, pectin and pulp","fruit juice, salt and acid","sugar, vinegar and milk","sugar, acid and pectin"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
