INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-188', 'deck-foodservice-ndle2021', 'A leadership style based on the ''majority rules'', in which decisions are made by the group rather than a manager alone.', 'Democratic', 'Democratic leadership involves group decision-making and voting.', '["People Power","Vox Populi, Vox Dei","Controlling","Democratic"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-189', 'deck-foodservice-ndle2021', 'The following agencies are responsible in ensuring the safety of our food products EXCEPT FOR:', 'Commission on Population', 'POPCOM handles population management, not food safety.', '["Department of Agriculture","Department of Health","Food and Drug Adrinistration","Commission on Population"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-190', 'deck-foodservice-ndle2021', 'The minimum temperature for sterilization for a certain length of time is:', '100 ½ C', 'Thermal sterilization requires temperatures exceeding boiling point (100°C / 121°C in autoclaves).', '["50 ½ C","100 ½ C","100 ½ F","0 ½ C"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-191', 'deck-foodservice-ndle2021', 'Rona, a product formulator, would like to assess consumers'' preference of five ice cream variants from ''most like'' to ''least like'' Which appropriate sensory evaluation method to use?', 'Ranking test', 'Ranking tests order multiple samples along an attribute or preference continuum.', '["Ranking test","Descriptive test","Paired comparison","Triangle test"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-192', 'deck-foodservice-ndle2021', 'Green tea, grapes and wine are high in phytonutrients called', 'Polyphenols', 'Catechins, resveratrol, and anthocyanins in tea/grapes are polyphenols.', '["Isoflavones","Terpenes","Polyphenols","Indoles"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-193', 'deck-foodservice-ndle2021', 'How many teaspoons are there in 1 tablespoon?', '3 tsps.', '1 tablespoon = 3 teaspoons = 15 mL.', '["5 tsps.","10 tsps.","3 tsps.","6 tsps."]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-194', 'deck-foodservice-ndle2021', 'Sandwiches and meals in the chiller of 711, Alfa Mart and Ministops are all', 'Ready prepared', 'Chilled cook-chill meals are ready-prepared foodservice models.', '["Ready prepared","Conventional","Commissary","Assembly served"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-195', 'deck-foodservice-ndle2021', 'egg noodles made from flour and duck''s eggs, salt, and soda:', 'Pancit Canton', 'Pancit Canton are pre-fried duck egg flour noodles.', '["Pancit Canton","Sotanghon","Bihon","Misua"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-196', 'deck-foodservice-ndle2021', 'made from rice or corn flour; the dough is extruded then boiled, cooled, and dried:', 'Bihon', 'Bihon (rice vermicelli) is extruded rice flour dough boiled and dried.', '["Pancit Canton","Sotanghon","Bihon","Miswa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-197', 'deck-foodservice-ndle2021', 'flat, yellowish noodles made from wheat flour, lye, and salt:', 'Miki', 'Miki noodles are yellow lye-treated wheat noodles.', '["Pancit Canton","Sotanghon","Miki","Miswa"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-198', 'deck-foodservice-ndle2021', 'Rancidity in fats, Maillard reaction, and non-enzymatic browning is what type of food spoilage?', 'Chemical', 'Lipid oxidation and non-enzymatic browning are chemical reactions.', '["Biochemical","Chemical","Physical","Microorganisms"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-199', 'deck-foodservice-ndle2021', 'It is a result from ingestion of foods containing preformed microbial toxins:', 'Food Intoxication', 'Food intoxication results from preformed bacterial toxins (e.g. S. aureus, C. botulinum).', '["Food Intoxication","Food Contamination","Food Infection","Food Protection"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('card-foodservice-ndle-200', 'deck-foodservice-ndle2021', 'It is a result from the ingestion of pathogen-contaminated food.', 'Food Infection', 'Food infection occurs when viable living pathogens colonize and multiply in the GI tract (e.g. Salmonella).', '["Food Intoxication","Food Contamination","Food Infection","Food Protection"]'::jsonb, '["Food Service Systems","NDLE 2021","Quizlet","Board Exam"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.022Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-01', 'deck-clinical-biochem-ndle', 'What is the recommended daily protein intake for an adult non-dialyzed patient with Chronic Kidney Disease (CKD) Stage 4 (eGFR 15–29 mL/min)?', '0.6 to 0.8 g/kg body weight/day', 'For non-dialyzed CKD Stages 3–5, KDIGO guidelines recommend a protein restriction of 0.6–0.8 g/kg/day to slow renal deterioration and reduce nitrogenous waste accumulation. Once hemodialysis begins, protein is elevated to 1.2–1.4 g/kg/day due to dialysate losses.', '["0.6 to 0.8 g/kg body weight/day","1.2 to 1.5 g/kg body weight/day","1.6 to 2.0 g/kg body weight/day","0.3 to 0.5 g/kg body weight/day"]'::jsonb, '["NBCD","Renal","Protein","MNT"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-02', 'deck-clinical-biochem-ndle', 'In a patient with Type 1 Diabetes Mellitus experiencing the Somogyi Effect, what is the underlying physiological mechanism and the correct nutritional/clinical intervention?', 'Nocturnal hypoglycemia followed by rebound morning hyperglycemia; decrease evening insulin or provide a bedtime carbohydrate-protein snack', 'The Somogyi effect occurs when nocturnal hypoglycemia triggers counter-regulatory hormones (epinephrine, glucagon, cortisol), causing rebound morning hyperglycemia. The remedy is to reduce evening insulin or provide a bedtime snack. In contrast, the Dawn Phenomenon is caused by early morning growth hormone surges without prior hypoglycemia.', '["Nocturnal hypoglycemia followed by rebound morning hyperglycemia; decrease evening insulin or provide a bedtime carbohydrate-protein snack","Early morning growth hormone surge without hypoglycemia; increase evening intermediate-acting insulin dose","Excessive hepatic gluconeogenesis due to cortisol deficiency; administer rapid-acting insulin at 3:00 AM","Reactive hyperglycemia triggered by high-protein dinner; eliminate all evening carbohydrates"]'::jsonb, '["NBCD","Diabetes","Endocrine","MNT"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-03', 'deck-clinical-biochem-ndle', 'Which of the following enteral feeding formulas is most indicated for a patient with severe malabsorption, short bowel syndrome, and pancreatic exocrine insufficiency?', 'Elemental (monomeric) formula with free amino acids and low fat (MCT oil)', 'Elemental (monomeric) formulas contain predigested nutrients—free amino acids, simple sugars, and minimal fat (primarily MCT oil)—requiring negligible enzymatic digestion and absorptive surface, making them ideal for short bowel syndrome and severe pancreatic insufficiency.', '["Elemental (monomeric) formula with free amino acids and low fat (MCT oil)","Polymeric intact protein formula with high complex dietary fiber","Blenderized whole food formula rich in long-chain triglycerides","Hypercaloric high-fat formula containing intact milk protein concentrates"]'::jsonb, '["NBCD","Enteral","MNT","GI"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-04', 'deck-clinical-biochem-ndle', 'What is the hallmark electrolyte hallmark that triggers the potentially fatal cardiac arrhythmias in Refeeding Syndrome during rapid nutrition repletion?', 'Severe Hypophosphatemia', 'During prolonged starvation, intracellular electrolytes deplete while serum levels appear normal. Upon carbohydrate re-feeding, sudden insulin secretion drives phosphate, potassium, and magnesium into cells to synthesize ATP, resulting in precipitous hypophosphatemia, cardiac failure, and respiratory arrest.', '["Severe Hypophosphatemia","Acute Hypercalcemia","Severe Hypernatremia","Refractory Hypermagnesemia"]'::jsonb, '["NBCD","Critical Care","Refeeding","Biochemistry"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-05', 'deck-clinical-biochem-ndle', 'A neonate diagnosed with Phenylketonuria (PKU) must strictly avoid phenylalanine while supplementing which conditionally essential amino acid?', 'Tyrosine', 'PKU results from a deficiency in phenylalanine hydroxylase (PAH), which normally converts phenylalanine to tyrosine. Due to this enzymatic block, phenylalanine accumulates neurotoxically, and tyrosine becomes conditionally essential and must be supplied exogenously in the diet.', '["Tyrosine","Tryptophan","Methionine","Valine"]'::jsonb, '["NBCD","Inborn Errors","Biochemistry","Pediatrics"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-06', 'deck-clinical-biochem-ndle', 'Which laboratory parameter is the primary biochemical indicator used to assess the effectiveness of long-term glycemic control over the past 2 to 3 months?', 'Glycated Hemoglobin (HbA1c)', 'Glycated hemoglobin (HbA1c) measures the non-enzymatic glycation of erythrocyte hemoglobin over the average 120-day red blood cell lifespan, reflecting mean blood glucose over the preceding 8–12 weeks. An HbA1c < 7.0% is standard target for non-pregnant adults with diabetes.', '["Glycated Hemoglobin (HbA1c)","Fasting Blood Glucose (FBG)","Serum Fructosamine level","Postprandial 2-hour capillary glucose"]'::jsonb, '["NBCD","Diabetes","Assessment","Clinical"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-07', 'deck-clinical-biochem-ndle', 'In a patient with Acute Pancreatitis, which enteral nutrition infusion route is preferred to minimize pancreatic enzyme stimulation while preserving gut mucosal integrity?', 'Nasojejunal (post-ligament of Treitz) continuous tube feeding', 'Nasojejunal feeding past the ligament of Treitz avoids cephalic, gastric, and duodenal stimulation of the exocrine pancreas, effectively resting the pancreas while preserving intestinal barrier function and reducing septic morbidity compared to TPN.', '["Nasojejunal (post-ligament of Treitz) continuous tube feeding","Nasogastric bolus gravity feeding every 4 hours","Percutaneous endoscopic gastrostomy (PEG) with nocturnal infusion","Total Parenteral Nutrition (TPN) via central venous catheter"]'::jsonb, '["NBCD","GI","Enteral","Pancreatitis"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-08', 'deck-clinical-biochem-ndle', 'What is the upper osmolarity threshold generally accepted for Total Parenteral Nutrition (TPN) administered through a Peripheral Venous Line (PPN)?', '900 mOsm/L', 'Peripheral Parenteral Nutrition (PPN) is restricted to solutions with osmolarity ≤ 900 mOsm/L (and typically ≤ 800 mOsm/L) to prevent phlebitis, chemical vein thrombosis, and extravasation injury. Solutions exceeding 900 mOsm/L require central venous access.', '["900 mOsm/L","1500 mOsm/L","500 mOsm/L","1800 mOsm/L"]'::jsonb, '["NBCD","Parenteral","Critical Care"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-09', 'deck-clinical-biochem-ndle', 'Which dietary recommendation is essential for managing Hepatic Encephalopathy in patients exhibiting episodic hyperammonemia while avoiding sarcopenia?', 'Maintain normoprotein intake (1.2–1.5 g/kg/day) using vegetable and dairy proteins rich in BCAA rather than severe protein restriction', 'Severe protein restriction is outdated and worsens muscle wasting, since skeletal muscle metabolizes ammonia. Current ESPEN/AASLD guidelines prescribe 1.2–1.5 g/kg/day, favoring dairy and vegetable proteins (higher BCAA to aromatic amino acid ratio) alongside lactulose.', '["Maintain normoprotein intake (1.2–1.5 g/kg/day) using vegetable and dairy proteins rich in BCAA rather than severe protein restriction","Enforce strict zero-protein diet (< 0.2 g/kg/day) until ammonia levels completely normalize","Prescribe high animal-based red meat diet supplemented with aromatic amino acids","Restrict total dietary carbohydrates to < 50 grams per day to suppress hepatic glycogenolysis"]'::jsonb, '["NBCD","Liver","MNT","Clinical"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-10', 'deck-clinical-biochem-ndle', 'Which vitamin deficiency presents with the classic triad of encephalopathy, oculomotor dysfunction (nystagmus), and gait ataxia (Wernicke-Korsakoff syndrome)?', 'Vitamin B1 (Thiamine)', 'Thiamine (Vitamin B1) serves as a coenzyme for pyruvate dehydrogenase and transketolase. In chronic alcoholism and severe hyperemesis, thiamine depletion halts cerebral glucose metabolism, precipitating Wernicke encephalopathy and Korsakoff psychosis.', '["Vitamin B1 (Thiamine)","Vitamin B3 (Niacin)","Vitamin B6 (Pyridoxine)","Vitamin B12 (Cobalamin)"]'::jsonb, '["NBCD","Vitamins","Biochemistry","Deficiencies"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-11', 'deck-clinical-biochem-ndle', 'What is the characteristic biochemical defect in Maple Syrup Urine Disease (MSUD), and which amino acids must be restricted?', 'Deficiency of branched-chain alpha-keto acid dehydrogenase; restrict Leucine, Isoleucine, and Valine', 'MSUD is an autosomal recessive metabolic disorder caused by deficient branched-chain alpha-ketoacid dehydrogenase (BCKAD), blocking oxidative decarboxylation of branched-chain amino acids (BCAA): leucine, isoleucine, and valine, resulting in sweet-smelling urine and encephalopathy.', '["Deficiency of branched-chain alpha-keto acid dehydrogenase; restrict Leucine, Isoleucine, and Valine","Deficiency of phenylalanine hydroxylase; restrict Phenylalanine and Alanine","Deficiency of cystathionine beta-synthase; restrict Methionine and Cysteine","Deficiency of homogentisate oxidase; restrict Tyrosine and Tryptophan"]'::jsonb, '["NBCD","Inborn Errors","Biochemistry"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-12', 'deck-clinical-biochem-ndle', 'For a patient experiencing dumping syndrome following a Billroth II subtotal gastrectomy, what is the most appropriate Medical Nutrition Therapy (MNT)?', 'Small, frequent meals rich in complex carbs and soluble fiber; fluids separated 30-45 minutes from meals; eliminate hyperosmolar simple sugars', 'Dumping syndrome occurs when hyperosmolar gastric chyme enters the jejunum rapidly. Management focuses on small, frequent meals, complex carbohydrates, soluble fiber (pectin/guar gum to delay transit), strictly avoiding simple sugars, and separating liquids from solids by 30–45 minutes.', '["Small, frequent meals rich in complex carbs and soluble fiber; fluids separated 30-45 minutes from meals; eliminate hyperosmolar simple sugars","Large, infrequent meals with generous warm sugary liquids taken directly during the meal","Strict high-carbohydrate, very low-fat liquid diet administered in 3 large boluses","High-sodium, high-sugar liquid formulas taken immediately upon finishing solid foods"]'::jsonb, '["NBCD","Surgery","GI","MNT"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-13', 'deck-clinical-biochem-ndle', 'Which vitamin is essential for the gamma-carboxylation of glutamic acid residues in clotting factors II, VII, IX, and X?', 'Vitamin K (Phylloquinone/Menaquinone)', 'Vitamin K acts as an essential cofactor for gamma-glutamyl carboxylase, which converts glutamate residues into gamma-carboxyglutamate (Gla) on blood coagulation factors II (prothrombin), VII, IX, and X, enabling calcium binding and clot cascade initiation.', '["Vitamin K (Phylloquinone/Menaquinone)","Vitamin E (Alpha-tocopherol)","Vitamin A (Retinol)","Vitamin D (Cholecalciferol)"]'::jsonb, '["NBCD","Vitamins","Biochemistry","Hematology"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-14', 'deck-clinical-biochem-ndle', 'What is the standard dietary sodium limit prescribed in the DASH (Dietary Approaches to Stop Hypertension) eating plan to achieve optimal blood pressure reduction?', '1,500 to 2,300 mg sodium per day', 'The standard DASH diet limits sodium to 2,300 mg/day, while the lower sodium DASH modification (1,500 mg/day) produces the greatest reductions in systolic and diastolic blood pressure, particularly in hypertensive and middle-aged/older adults.', '["1,500 to 2,300 mg sodium per day","3,000 to 4,000 mg sodium per day","500 to 800 mg sodium per day","4,500 to 5,500 mg sodium per day"]'::jsonb, '["NBCD","Cardiovascular","MNT","Hypertension"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-15', 'deck-clinical-biochem-ndle', 'Which biochemical pathway produces NADPH required for fatty acid biosynthesis and glutathione reduction, while generating ribose-5-phosphate for nucleotide synthesis?', 'Pentose Phosphate Pathway (Hexose Monophosphate Shunt)', 'The Pentose Phosphate Pathway (HMP shunt) branches from glucose-6-phosphate to yield NADPH (essential for reductive biosynthesis of lipids and preserving reduced glutathione against oxidative stress) and ribose-5-phosphate (nucleic acid backbone).', '["Pentose Phosphate Pathway (Hexose Monophosphate Shunt)","Tricarboxylic Acid (Krebs) Cycle","Cori Cycle in liver and erythrocytes","Beta-oxidation of long-chain fatty acids"]'::jsonb, '["NBCD","Biochemistry","Metabolism"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-16', 'deck-clinical-biochem-ndle', 'In severe burn injury, which formula is traditionally utilized to estimate the daily caloric requirements during the hypermetabolic flow phase?', 'Curreri Formula: (25 kcal × kg body weight) + (40 kcal × % TBSA burned)', 'The Curreri formula estimates daily energy needs in burn patients as 25 kcal/kg + (40 kcal × % total body surface area burned). Although indirect calorimetry is gold standard, Curreri provides a recognized clinical benchmark for hypermetabolism in severe thermal trauma.', '["Curreri Formula: (25 kcal × kg body weight) + (40 kcal × % TBSA burned)","Harris-Benedict Formula multiplied by a stress factor of 1.1","Mifflin-St Jeor Equation with a fixed 500 kcal reduction","Penn State Equation (2003) with zero thermal adjustment"]'::jsonb, '["NBCD","Critical Care","Burns","Calculations"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-17', 'deck-clinical-biochem-ndle', 'A patient taking the anticoagulant Warfarin (Coumadin) requires which vital dietary counseling regarding Vitamin K?', 'Maintain a consistent, steady daily intake of Vitamin K rather than drastic avoidance or sudden surges', 'Warfarin acts as a Vitamin K antagonist. Sudden spikes in Vitamin K intake (e.g., kale, spinach) overcome warfarin and decrease the International Normalized Ratio (INR), risking thrombosis, while sudden deprivation increases bleeding risk. Consistency is key.', '["Maintain a consistent, steady daily intake of Vitamin K rather than drastic avoidance or sudden surges","Completely eliminate all green leafy vegetables and vegetable oils from the diet","Take high-dose Vitamin K supplements every morning with the anticoagulant tablet","Switch entirely to a raw vegan diet containing at least 1,000 mcg Vitamin K daily"]'::jsonb, '["NBCD","Drug-Nutrient","Cardiovascular","Clinical"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-18', 'deck-clinical-biochem-ndle', 'Which of the following clinical conditions warrants the initiation of a strict Gluten-Free Diet due to autoimmune enteropathy triggered by gliadin peptides?', 'Celiac Disease (Gluten-sensitive enteropathy)', 'Celiac disease is an immune-mediated enteropathy triggered by ingested gluten (specifically gliadin peptides found in wheat, barley, rye), resulting in mucosal inflammation, crypt hyperplasia, and villous blunting in the small intestine.', '["Celiac Disease (Gluten-sensitive enteropathy)","Diverticulosis of the sigmoid colon","Irritable Bowel Syndrome - Constipation predominant","Gastroesophageal Reflux Disease (GERD)"]'::jsonb, '["NBCD","GI","MNT","Allergy"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-19', 'deck-clinical-biochem-ndle', 'What is the Nitrogen-to-Protein conversion factor standardly used in clinical nitrogen balance calculations for whole intact mixed dietary proteins?', '6.25 (Protein contains approximately 16% nitrogen)', 'Most intact food proteins contain approximately 16% nitrogen by weight (100 / 16 = 6.25). Therefore: Nitrogen (g) = Protein intake (g) / 6.25. Nitrogen balance = Nitrogen In - (Urinary Urea Nitrogen + 4 g obligate losses).', '["6.25 (Protein contains approximately 16% nitrogen)","5.71 (Protein contains approximately 17.5% nitrogen)","8.00 (Protein contains approximately 12.5% nitrogen)","4.18 (Protein contains approximately 24% nitrogen)"]'::jsonb, '["NBCD","Calculations","Biochemistry","Clinical"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('nbcd-cble-20', 'deck-clinical-biochem-ndle', 'Which mineral deficiency is most commonly implicated in impaired wound healing, hypogeusia (blunted taste sensation), alopecia, and compromised cell-mediated immunity?', 'Zinc', 'Zinc is an indispensable catalytic and structural cofactor for > 300 metalloenzymes, including DNA/RNA polymerases and matrix metalloproteinases required for collagen synthesis, epithelial re-epithelialization, taste bud gustin function, and T-lymphocyte proliferation.', '["Zinc","Copper","Selenium","Chromium"]'::jsonb, '["NBCD","Minerals","Wound Healing","Deficiencies"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-01', 'deck-cphn-ndle-bank', 'Under Republic Act No. 11148 (Kalusugan at Nutrisyon ng Mag-Nanay Act), which critical window of opportunity is prioritized to prevent irreversible stunting and neurodevelopmental deficits?', 'The First 1,000 Days of Life (from conception through the child''s second birthday)', 'RA 11148 institutionalizes maternal and child nutrition across the First 1,000 Days—covering roughly 270 days of pregnancy, 365 days of infancy (0–12 months), and 365 days of toddlerhood (13–24 months). Interventions during this window prevent irreversible physical stunting and cognitive deficits.', '["The First 1,000 Days of Life (from conception through the child''s second birthday)","The pre-school period from 3 to 5 years of age","Early adolescence during the pubertal growth spurt (10–14 years)","School-age years from Kindergarten through Grade 6 (5–12 years)"]'::jsonb, '["CPHN","Laws","First 1000 Days","Maternal & Child"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-02', 'deck-cphn-ndle-bank', 'In the annual nationwide Operation Timbang (OPT) Plus protocol of the National Nutrition Council (NNC), which anthropometric index is specifically utilized to assess "Wasting" or acute malnutrition among children aged 0–59 months?', 'Weight-for-Length / Weight-for-Height (WFL/WFH)', 'Under WHO Child Growth Standards adopted by the Philippines, Weight-for-Length/Height (WFL/WFH) reflects acute nutritional deficit (wasting/thinness or overweight), Length/Height-for-Age (LFA/HFA) reflects chronic malnutrition (stunting), and Weight-for-Age (WFA) reflects general underweight.', '["Weight-for-Length / Weight-for-Height (WFL/WFH)","Length/Height-for-Age (LFA/HFA)","Weight-for-Age (WFA)","Head Circumference-for-Age (HCFA)"]'::jsonb, '["CPHN","Assessment","OPT Plus","Anthropometry"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-03', 'deck-cphn-ndle-bank', 'According to the Philippine Food Fortification Act of 2000 (Republic Act No. 8976), which mandatory staple foods are fortified with specific micronutrients under national law?', 'Rice (with Iron), Wheat Flour (with Vitamin A & Iron), Refined Sugar (with Vitamin A), and Cooking Oil (with Vitamin A)', 'RA 8976 mandates the fortification of four staple foods: milled rice with Iron; wheat flour with Vitamin A and Iron; refined sugar with Vitamin A; and refined cooking oil with Vitamin A. Voluntary fortification of processed foods is recognized with the Sangkap Pinoy seal.', '["Rice (with Iron), Wheat Flour (with Vitamin A & Iron), Refined Sugar (with Vitamin A), and Cooking Oil (with Vitamin A)","Iodized Salt (with Iodine), Milk (with Calcium), Brown Rice (with Thiamine), and Soy Sauce (with Iron)","Cornstarch (with Zinc), Table Sugar (with Chromium), Vinegar (with Potassium), and Bottled Water (with Fluoride)","Cassava Flour (with Folic Acid), Coconut Oil (with Vitamin D), Canned Tuna (with Omega-3), and Bread (with Riboflavin)"]'::jsonb, '["CPHN","Laws","Food Fortification","Micronutrients"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-04', 'deck-cphn-ndle-bank', 'What is the diagnostic Mid-Upper Arm Circumference (MUAC) cutoff used during community disaster and rapid screening to classify Severe Acute Malnutrition (SAM) in children 6 to 59 months?', 'MUAC < 115 mm (< 11.5 cm) or presence of bilateral pitting edema', 'Per WHO and Philippine DOH guidelines for Management of Severe Acute Malnutrition, a child 6–59 months with MUAC < 115 mm (red zone on the Shakir strip) or with bilateral pitting edema (+, ++, or +++) is classified as having SAM requiring emergency therapeutic feeding (RUTF/F-75).', '["MUAC < 115 mm (< 11.5 cm) or presence of bilateral pitting edema","MUAC between 115 mm and 125 mm with moderate pallor","MUAC < 135 mm (< 13.5 cm) with history of diarrhea","MUAC between 125 mm and 140 mm without clinical edema"]'::jsonb, '["CPHN","SAM","Assessment","Emergency Nutrition"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-05', 'deck-cphn-ndle-bank', 'Under Executive Order No. 51 (The Philippine Milk Code), which of the following activities by infant formula manufacturers is strictly prohibited in health facilities and public spaces?', 'Direct consumer advertising, distribution of free infant formula samples, and sponsorship of clinical gifts to healthcare workers', 'EO 51 (Philippine Milk Code) strictly bans advertising, point-of-sale promotional displays, free formula samples to mothers, and company-sponsored gifts or incentives to healthcare personnel, safeguarding and promoting exclusive breastfeeding for infants 0–6 months.', '["Direct consumer advertising, distribution of free infant formula samples, and sponsorship of clinical gifts to healthcare workers","Selling infant formula in licensed commercial retail pharmacies with clear medical prescription","Labeling expiration dates and nutritional panels on infant formula containers in the Filipino language","Publishing peer-reviewed laboratory research in academic pediatric medical journals"]'::jsonb, '["CPHN","Laws","Milk Code","Breastfeeding"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-06', 'deck-cphn-ndle-bank', 'What is the standard DOH high-dose Vitamin A capsule dosage administered to infants aged 6 to 11 months during nationwide Garantisadong Pambata campaigns?', '100,000 International Units (IU) - Blue Capsule (single dose)', 'In the Philippine national micronutrient supplementation program, infants 6–11 months receive a single dose of 100,000 IU Vitamin A (blue capsule). Children 12–59 months receive 200,000 IU (red capsule) every six months to prevent xerophthalmia and reduce all-cause mortality.', '["100,000 International Units (IU) - Blue Capsule (single dose)","200,000 International Units (IU) - Red Capsule (single dose)","50,000 International Units (IU) - Yellow Capsule (daily dose)","500,000 International Units (IU) - Green Capsule (annual dose)"]'::jsonb, '["CPHN","Supplementation","Vitamin A","Public Health"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-07', 'deck-cphn-ndle-bank', 'Which dietary assessment methodology is most susceptible to the "flat-slope syndrome," where low-intake respondents tend to overreport and high-intake respondents tend to underreport food consumption?', '24-Hour Food Recall', 'The 24-hour food recall is vulnerable to flat-slope syndrome (social desirability bias), where respondents distort their reports toward what is perceived as normal: lean/low-intake subjects overreport, and overweight/high-intake subjects underreport their food intake.', '["24-Hour Food Recall","Weighed Food Intake Record","Duplicate Diet Chemical Analysis","Food Balance Sheet (FBS)"]'::jsonb, '["CPHN","Assessment","Methodology","Biostatistics"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-08', 'deck-cphn-ndle-bank', 'In epidemiologic studies of nutrition and chronic disease, how is the "Relative Risk" (Risk Ratio) correctly defined and interpreted?', 'The ratio of the incidence of disease among the exposed group to the incidence of disease among the unexposed group (Cohort study)', 'Relative Risk (RR) = [Incidence in Exposed] / [Incidence in Unexposed]. An RR > 1.0 signifies positive association (risk factor), RR = 1.0 signifies no association, and RR < 1.0 signifies protective effect. RR is directly calculated from prospective cohort studies.', '["The ratio of the incidence of disease among the exposed group to the incidence of disease among the unexposed group (Cohort study)","The ratio of the odds of exposure among cases to the odds of exposure among controls (Case-Control study)","The total number of existing disease cases in a community divided by the total population at one specific point in time","The proportion of disease-free individuals who test positive on a diagnostic screening tool"]'::jsonb, '["CPHN","Epidemiology","Biostatistics","Research"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-09', 'deck-cphn-ndle-bank', 'What is the overarching goal of the Philippine Plan of Action for Nutrition (PPAN 2023–2028) regarding the national prevalence of childhood stunting among children under five years?', 'Reduce the prevalence of stunting to less than 17.9% through life-stage interventions and nutrition-sensitive agricultural and social programs', 'The PPAN 2023–2028 targets significant reductions in childhood stunting (from ~26.7% down below 17.9%), wasting (< 5%), and maternal undernutrition through combined nutrition-specific interventions, nutrition-sensitive programs, and enabling policy environments.', '["Reduce the prevalence of stunting to less than 17.9% through life-stage interventions and nutrition-sensitive agricultural and social programs","Eliminate all forms of obesity while allowing stunting levels to plateau naturally","Transition entire agricultural land to exclusive organic vegetable production by 2025","Replace all complementary feeding with commercial synthetic nutritional formula pills"]'::jsonb, '["CPHN","PPAN","NNC","Public Health"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-10', 'deck-cphn-ndle-bank', 'According to Republic Act No. 8172 (An Act for Salt Iodization Nationwide - ASIN Law), what is the minimum required iodine content in salt at the retail consumer level?', '30 to 70 parts per million (ppm) of iodine', 'The revised implementing rules and regulations of the ASIN Law (RA 8172) require iodized salt at the retail/household level to contain 30–70 ppm (mg/kg) of iodine to prevent Iodine Deficiency Disorders (IDD), endemic goiter, and cretinism in the Philippines.', '["30 to 70 parts per million (ppm) of iodine","5 to 10 parts per million (ppm) of iodine","100 to 200 parts per million (ppm) of iodine","500 to 800 parts per million (ppm) of iodine"]'::jsonb, '["CPHN","Laws","ASIN Law","Iodine"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-11', 'deck-cphn-ndle-bank', 'In community nutrition management of Severe Acute Malnutrition (SAM), what is the primary therapeutic milk used in the initial Inpatient Stabilization Phase (Phase 1)?', 'F-75 therapeutic formula (75 kcal and 0.9 g protein per 100 mL)', 'F-75 formula (75 kcal and 0.9 g protein per 100 mL) is designed strictly for Phase 1 Stabilization to restore metabolic and electrolyte balance without overloading the fragile liver, kidneys, and myocardium. Once appetite returns and edema subsides, transition to F-100 or RUTF occurs.', '["F-75 therapeutic formula (75 kcal and 0.9 g protein per 100 mL)","F-100 catch-up formula (100 kcal and 2.9 g protein per 100 mL)","Full-cream condensed sweetened cow milk diluted 1:1 with distilled water","High-solute unpasteurized skim milk enriched with table salt and raw egg yolks"]'::jsonb, '["CPHN","SAM","Therapeutics","Malnutrition"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-12', 'deck-cphn-ndle-bank', 'What visual food guide model was created by the Food and Nutrition Research Institute (DOST-FNRI) to demonstrate the ideal proportional balance of Go, Grow, and Glow foods on a per-meal plate for Filipino adults?', 'Pinggang Pinoy', 'Pinggang Pinoy, developed by DOST-FNRI in collaboration with DOH and WHO, uses a familiar plate model to visually represent the recommended proportion of energy-giving (Go), body-building (Grow), and body-regulating (Glow) foods per meal, complementing the Daily Nutritional Guide (DNG) Pyramid.', '["Pinggang Pinoy","Daily Nutritional Guide (DNG) Pyramid","MyPlate by the USDA","10 Kumainments"]'::jsonb, '["CPHN","FNRI","Pinggang Pinoy","Education"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-13', 'deck-cphn-ndle-bank', 'What is the daily elemental iron and folic acid supplementation recommendation for pregnant women in the Philippines to prevent maternal anemia and neural tube defects?', '60 mg elemental iron and 400 mcg folic acid daily throughout pregnancy for at least 180 days', 'DOH Administrative Order mandates that all pregnant women receive 60 mg of elemental iron combined with 400 mcg (0.4 mg) of folic acid daily as early as possible in pregnancy for a duration of at least 180 days (6 months) to avert maternal anemia, low birth weight, and neural tube closure defects.', '["60 mg elemental iron and 400 mcg folic acid daily throughout pregnancy for at least 180 days","10 mg elemental iron and 100 mcg folic acid weekly during the third trimester only","150 mg elemental iron and 5,000 mcg folic acid twice daily throughout lactation","Zero iron supplementation unless serum ferritin drops below 5 ng/mL"]'::jsonb, '["CPHN","Maternal","Supplementation","Iron-Folate"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-14', 'deck-cphn-ndle-bank', 'When evaluating a community nutrition program, what is the distinction between "Process Evaluation" and "Outcome/Impact Evaluation"?', 'Process evaluation monitors program fidelity, activities, and reach; Outcome evaluation measures changes in nutritional status, knowledge, and clinical endpoints', 'Process evaluation checks implementation quality (e.g., number of mothers trained, food packs distributed, adherence to protocol). Outcome/Impact evaluation determines whether the intervention actually changed nutritional status (e.g., reductions in stunting rates or anemia prevalence).', '["Process evaluation monitors program fidelity, activities, and reach; Outcome evaluation measures changes in nutritional status, knowledge, and clinical endpoints","Process evaluation assesses national mortality statistics; Outcome evaluation assesses daily volunteer attendance logs","Process evaluation is performed only after program closure; Outcome evaluation is conducted prior to project funding","Process evaluation measures genetic mutations; Outcome evaluation measures budgetary financial audits"]'::jsonb, '["CPHN","Program Evaluation","Public Health","Management"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-15', 'deck-cphn-ndle-bank', 'In a disaster or emergency evacuation center, what is the minimum daily per capita energy planning threshold recommended by the SPHERE Project and adopted in Philippine Nutrition in Emergencies (NiE)?', '2,100 kcal per person per day', 'The SPHERE Humanitarian Charter and Philippine Nutrition in Emergencies guidelines establish a standard planning figure of 2,100 kcal per person per day (with 10–12% of total energy from protein and 17% from fat) for general food distributions to maintain basic nutritional survival in disaster-affected populations.', '["2,100 kcal per person per day","1,200 kcal per person per day","3,500 kcal per person per day","1,600 kcal per person per day"]'::jsonb, '["CPHN","Emergency Nutrition","SPHERE","Disaster"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-16', 'deck-cphn-ndle-bank', 'What is the diagnostic difference between "Marasmus" and "Kwashiorkor" when assessing acute protein-energy malnutrition in the field?', 'Kwashiorkor features bilateral pitting edema, moon face, and flaky-paint dermatosis; Marasmus features severe subcutaneous fat and muscle wasting without edema (old man face)', 'Kwashiorkor is characterized by bilateral pedal/pretibial pitting edema, fatty liver, preserved subcutaneous fat, apathy, and skin lesions (flaky paint/enamel dermatosis) due to acute protein deficiency with relative carbohydrate sufficiency. Marasmus presents as gross somatic muscle and fat wasting without edema due to severe overall caloric starvation.', '["Kwashiorkor features bilateral pitting edema, moon face, and flaky-paint dermatosis; Marasmus features severe subcutaneous fat and muscle wasting without edema (old man face)","Kwashiorkor is due to exclusive Vitamin C deficiency; Marasmus is due to toxic Vitamin A excess","Kwashiorkor presents with severe dehydration and zero edema; Marasmus presents with generalized anasarca and ascites","Kwashiorkor occurs only in adults over 65 years; Marasmus occurs exclusively in exclusively breastfed neonates"]'::jsonb, '["CPHN","Malnutrition","Assessment","Clinical-Community"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-17', 'deck-cphn-ndle-bank', 'Under the Expanded Breastfeeding Promotion Act of 2009 (Republic Act No. 10028), what workplace accommodation is required for lactating employees?', 'Lactation stations with basic washing and refrigeration facilities, plus paid lactation break periods of not less than 40 minutes per 8-hour working day', 'RA 10028 mandates lactation stations in all health and non-health workplaces, accessible to lactating mothers, equipped with refrigeration or ice coolers, running water, and paid lactation periods totaling not less than 40 minutes for every 8-hour working shift.', '["Lactation stations with basic washing and refrigeration facilities, plus paid lactation break periods of not less than 40 minutes per 8-hour working day","Mandatory provision of commercial powdered milk dispensers and sterilizing autoclaves in common staff canteens","Permanent exemption from all workplace duties with full paid leave until the child reaches 6 years of age","A single 5-minute unpaid bathroom break per 12-hour factory shift"]'::jsonb, '["CPHN","Laws","Breastfeeding","Workplace"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-18', 'deck-cphn-ndle-bank', 'Which biochemical biomarker is standardly utilized in national demographic and health surveys (NDHS / NNS) to assess the prevalence of Iodine Deficiency Disorders (IDD) at the population level?', 'Median Urinary Iodine Concentration (mUIC) in mcg/L among school-age children and pregnant women', 'Urinary iodine excretion reflects recent iodine intake, as > 90% of ingested iodine is excreted by the kidneys. WHO/UNICEF/ICCIDD benchmark: a population median UIC of 100–199 mcg/L in school-age children indicates adequate iodine nutrition, while < 100 mcg/L indicates population deficiency.', '["Median Urinary Iodine Concentration (mUIC) in mcg/L among school-age children and pregnant women","Serum total cholesterol level in adult males","24-hour fecal sodium excretion in hypertensive patients","Hair mineral zinc-to-copper atomic mass ratio"]'::jsonb, '["CPHN","Assessment","Biomarkers","Iodine"]'::jsonb, NULL, 'hard', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-19', 'deck-cphn-ndle-bank', 'What is the term for the concurrent manifestation of undernutrition (stunting and wasting) alongside micronutrient deficiencies and overweight/obesity within the same country, household, or individual?', 'The Triple Burden of Malnutrition', 'The "Triple Burden of Malnutrition" refers to the coexistence of undernutrition (stunting and wasting), micronutrient deficiencies ("hidden hunger"), and overweight/obesity with non-communicable diseases (NCDs) affecting low- and middle-income countries like the Philippines undergoing rapid nutritional transition.', '["The Triple Burden of Malnutrition","The Barker Fetal Origins Hypothesis","The Epidemiological Transition Paradox","The Somogyi Metabolic Phenomenon"]'::jsonb, '["CPHN","Public Health","Nutrition Transition","Epidemiology"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cphn-cble-20', 'deck-cphn-ndle-bank', 'In infant and young child feeding (IYCF), what is the WHO/UNICEF recommended timeline for initiating exclusive breastfeeding and subsequent complementary feeding?', 'Initiate breastfeeding within the first hour of birth; exclusively breastfeed for 6 months; introduce safe, nutrient-dense complementary foods at 6 months while continuing breastfeeding up to 2 years or beyond', 'Global and Philippine IYCF guidelines prescribe: early initiation of breastfeeding within the first hour of delivery (essential for colostrum); exclusive breastfeeding for the first 6 months of life; and introduction of safe, adequate complementary foods at 6 months alongside continued breastfeeding up to 2 years and beyond.', '["Initiate breastfeeding within the first hour of birth; exclusively breastfeed for 6 months; introduce safe, nutrient-dense complementary foods at 6 months while continuing breastfeeding up to 2 years or beyond","Initiate sugar water at 24 hours post-delivery; begin solid rice porridge at 2 months; terminate breastfeeding at 6 months","Exclusively feed formula for the first 12 months; delay any solid foods until all deciduous teeth have erupted","Initiate complementary pureed fruits at 3 months; replace all breastmilk with cow milk by the 5th month"]'::jsonb, '["CPHN","IYCF","Maternal & Child","Breastfeeding"]'::jsonb, NULL, 'easy', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-1', 'deck-cble-mock-bank', 'A 58-year-old male with Stage 4 Chronic Kidney Disease (non-dialysis) has a GFR of 22 mL/min/1.73m² and weighs 70 kg (ideal body weight). What is the recommended daily protein intake range for this patient according to KDOQI guidelines to delay progression of renal failure?', '0.55 – 0.60 g/kg body weight/day, or 0.28 – 0.43 g/kg with keto acid analogs', 'According to the updated KDOQI Clinical Practice Guideline for Nutrition in CKD, in adults with CKD 3-5 who are metabolically stable and non-dialysis dependent, dietary protein restriction of 0.55 to 0.60 g/kg/day (or 0.28-0.43 g/kg/day with keto acid analogs) is recommended to reduce risk of end-stage kidney disease and mortality.', '["0.55 – 0.60 g/kg body weight/day, or 0.28 – 0.43 g/kg with keto acid analogs","0.80 – 1.00 g/kg body weight/day with high biological value protein","1.20 – 1.40 g/kg body weight/day to prevent protein-energy wasting","1.50 – 2.00 g/kg body weight/day supplemented with essential amino acids"]'::jsonb, '["Mock Exam","Renal Nutrition"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-2', 'deck-cble-mock-bank', 'Refer to the Nutrition Facts label below. If a patient consumes 2 servings of this food item, what total percentage of the Daily Value (% DV) of dietary fiber and total grams of carbohydrates will they have consumed?', '28% DV Fiber, 62g Total Carbohydrates', 'Per serving: Dietary Fiber is 4g (14% DV) and Total Carbohydrate is 31g. For 2 servings: Dietary Fiber = 14% * 2 = 28% DV, and Total Carbohydrate = 31g * 2 = 62g.', '["28% DV Fiber, 62g Total Carbohydrates","14% DV Fiber, 31g Total Carbohydrates","22% DV Fiber, 50g Total Carbohydrates","20% DV Fiber, 60g Total Carbohydrates"]'::jsonb, '["Mock Exam","Food Composition & Labeling"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-3', 'deck-cble-mock-bank', 'A post-operative gastrectomy patient experiences diaphoresis, lightheadedness, abdominal cramping, and explosive diarrhea 20 minutes after ingestion of a high-simple-sugar meal. Which physiological mechanism primarily triggers this ''Early Dumping Syndrome''?', 'Hyperosmolar chyme entering the jejunum causing a rapid fluid shift from intravascular space into the intestinal lumen', 'Early dumping syndrome occurs 10-30 minutes post-meal due to the sudden dump of hypertonic food contents into the proximal jejunum, causing a rapid shift of extracellular fluid into the bowel lumen, resulting in hypotension, tachycardia, flushing, and cramping.', '["Hyperosmolar chyme entering the jejunum causing a rapid fluid shift from intravascular space into the intestinal lumen","Excessive reactive insulin secretion in response to rapid glucose absorption resulting in rebound hypoglycemia","Impaired secretion of cholecystokinin (CCK) leading to inadequate pancreatic lipase activation","Bacterial overgrowth in the blind loop fermenting unabsorbed oligosaccharides into short-chain fatty acids"]'::jsonb, '["Mock Exam","Gastrointestinal Disorders"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-4', 'deck-cble-mock-bank', 'Using the Harris-Benedict Formula and standard clinical assessment, calculate the Total Energy Requirement (TER) for a 45-year-old female weighing 60 kg, height 160 cm, with moderate trauma (Stress factor = 1.3, Activity factor = 1.2 in bed).
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-5', 'deck-cble-mock-bank', 'Examine the clinical chart diagram below illustrating the Nitrogen Balance equilibrium equation. A burn patient has a 24-hour Urinary Urea Nitrogen (UUN) of 16 grams and a daily dietary protein intake of 75 grams. What is the patient''s Nitrogen Balance state?', '-8 g N/day (Severe negative nitrogen balance / catabolism)', 'Nitrogen Intake = 75 g / 6.25 = 12 g N. Nitrogen Output = 16 g (UUN) + 4 g (insensible losses) = 20 g N. Nitrogen Balance = 12 g - 20 g = -8 g N/day, indicating hypercatabolic state requiring increased protein prescription.', '["-8 g N/day (Severe negative nitrogen balance / catabolism)","+4 g N/day (Optimal anabolic state)","-4 g N/day (Mild negative nitrogen balance)","0 g N/day (Equilibrium state)"]'::jsonb, '["Mock Exam","Critical Care Nutrition"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-6', 'deck-cble-mock-bank', 'In the Nutrition Care Process (NCP), which of the following represents a properly structured PES statement for a patient with newly diagnosed Type 2 Diabetes Mellitus?', 'Excessive carbohydrate intake (NI-5.8.2) related to frequent consumption of sugar-sweetened beverages as evidenced by HbA1c of 9.2% and food diary showing 350g CHO/day.', 'A standard PES statement follows Problem (Nutrition Diagnostic Term), Etiology (root cause linked by ''related to''), and Signs/Symptoms (objective or subjective data linked by ''as evidenced by''). Option A correctly targets a nutrition diagnosis rather than a medical diagnosis.', '["Excessive carbohydrate intake (NI-5.8.2) related to frequent consumption of sugar-sweetened beverages as evidenced by HbA1c of 9.2% and food diary showing 350g CHO/day.","Type 2 Diabetes Mellitus related to insulin resistance as evidenced by elevated fasting blood glucose of 185 mg/dL.","Inability to manage carbohydrate intake caused by lack of medical compliance as evidenced by high glycemic spikes.","Elevated HbA1c related to excessive dietary sugar as evidenced by physician consultation and prescription of Metformin."]'::jsonb, '["Mock Exam","Nutrition Care Process (NCP)"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-7', 'deck-cble-mock-bank', 'Which of the following biochemical parameters is the most sensitive early laboratory indicator of refeeding syndrome in a severely malnourished patient initiated on total parenteral nutrition (TPN)?', 'Hypophosphatemia (Rapid drop in serum phosphorus)', 'Refeeding syndrome is characterized by rapid intracellular shifts of electrolytes when carbohydrates are reintroduced. Insulin stimulates cellular uptake of glucose, potassium, magnesium, and particularly phosphate (required for ATP generation and glycolysis), leading to life-threatening hypophosphatemia.', '["Hypophosphatemia (Rapid drop in serum phosphorus)","Hyperkalemia (Elevated serum potassium)","Hypoalbuminemia (Decreased serum albumin)","Elevated Blood Urea Nitrogen (BUN)"]'::jsonb, '["Mock Exam","Enteral & Parenteral Nutrition"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-8', 'deck-cble-mock-bank', 'A client with Phenylketonuria (PKU) must strictly limit dietary intake of phenylalanine. Because phenylalanine hydroxylase is deficient, which amino acid becomes conditionally essential and must be supplied adequately in the diet?', 'Tyrosine', 'Phenylalanine is normally converted to tyrosine via the enzyme phenylalanine hydroxylase. In PKU, this pathway is impaired, making tyrosine a conditionally essential amino acid that must be provided in the diet.', '["Tyrosine","Tryptophan","Methionine","Cysteine"]'::jsonb, '["Mock Exam","Inborn Errors of Metabolism"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-9', 'deck-cble-mock-bank', 'According to the Food Exchange Lists for Diabetes in the Philippines (FNRI), 1 exchange of Medium-Fat Meat provides approximately how many grams of Protein and Fat, and how much Energy?', '8g Protein, 6g Fat, 86 kcal', 'According to the Philippine Food Exchange List (FNRI): Low fat meat = 8g PRO, 1g FAT (41 kcal); Medium fat meat = 8g PRO, 6g FAT (86 kcal); High fat meat = 8g PRO, 10g FAT (122 kcal).', '["8g Protein, 6g Fat, 86 kcal","8g Protein, 1g Fat, 41 kcal","8g Protein, 10g Fat, 122 kcal","7g Protein, 5g Fat, 75 kcal"]'::jsonb, '["Mock Exam","Food Exchange Lists"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, sm2, updated_at) VALUES ('cble-extra-10', 'deck-cble-mock-bank', 'A patient on Warfarin (Coumadin) anticoagulant therapy should be provided which key nutritional guidance regarding their dietary vitamin K consumption?', 'Maintain a consistent daily intake of vitamin K-rich foods rather than eliminating or radically increasing them', 'Warfarin acts as a Vitamin K antagonist. Consistency in daily vitamin K intake is critical to maintain a stable INR (International Normalized Ratio). Drastic increases or decreases in vitamin K can lead to subtherapeutic or supratherapeutic anticoagulation.', '["Maintain a consistent daily intake of vitamin K-rich foods rather than eliminating or radically increasing them","Strictly avoid all green leafy vegetables (kale, spinach, collard greens) indefinitely","Double daily dietary vitamin K intake on days when INR levels are high","Take high-dose Vitamin E supplements to enhance the anticoagulant efficacy of Warfarin"]'::jsonb, '["Mock Exam","Drug-Nutrient Interactions"]'::jsonb, NULL, 'medium', 1, '{"interval":1,"easeFactor":2.5,"repetitions":0,"dueDate":"2026-08-15T14:53:04.021Z"}'::jsonb, NOW()) ON CONFLICT (id) DO UPDATE SET front = EXCLUDED.front, back = EXCLUDED.back, rationale = EXCLUDED.rationale, options = EXCLUDED.options, tags = EXCLUDED.tags, ndle_subject = EXCLUDED.ndle_subject, difficulty = EXCLUDED.difficulty, leitner_box = EXCLUDED.leitner_box, sm2 = EXCLUDED.sm2, updated_at = NOW();